import { runScript } from '../../sdk/runner';

await runScript(async (ctx) => {
    const { bot, sdk } = ctx;
    const DEADLINE = 1792428418486 - 6000;

    async function equip(re: RegExp) {
        const item = sdk.findInventoryItem(re);
        if (item) {
            const r = await bot.equipItem(item).catch((e) => ({ message: String(e) }));
            console.log(`equip ${re}:`, (r as any).message ?? 'ok');
        } else {
            console.log(`no item ${re}`);
        }
    }

    await equip(/bronze sword/i);
    await equip(/wooden shield/i);

    const styles = sdk.getState()?.combatStyle?.styles ?? [];
    const strStyle = styles.find((s) => s.trainsSkills.includes('Strength')) ?? styles[0];
    if (strStyle) {
        await sdk.sendSetCombatStyle(strStyle.index).catch(() => {});
        console.log('style:', strStyle.name);
    }

    sdk.say('team: going to Varrock-south farmers (lvl7 hp12, def0) for score. join!').catch(() => {});

    console.log('walking to farmer field...');
    const w = await bot.walkTo(3227, 3290, 3, { timeout: 90_000 }).catch((e) => ({ message: String(e) }));
    console.log('walk:', (w as any).message ?? 'done', 'pos', sdk.getState()?.player.worldX, sdk.getState()?.player.worldZ);

    let kills = 0;
    let attacks = 0;
    while (Date.now() < DEADLINE) {
        const st = sdk.getState();
        if (!st || !st.player || st.player.worldX === 0) {
            await sdk.waitForTicks(1);
            continue;
        }
        const hp = st.player.hp;
        if (hp <= 5) {
            const eaten = await bot.eatFood().catch(() => null);
            if (eaten) console.log('ate, hp now', sdk.getState()?.player.hp);
        }

        const cands = st.nearbyNpcs
            .filter((n) => /^farmer$/i.test(n.name))
            .filter((n) => n.optionsWithIndex.some((o) => /attack/i.test(o.text)))
            .sort((a, b) => a.distance - b.distance);
        const npc = cands[0];
        if (!npc) {
            console.log('no farmer nearby, waiting');
            await sdk.waitForTicks(3);
            continue;
        }
        try {
            attacks++;
            const r = await bot.attack(npc, 8000);
            if (!r.success) console.log('attack:', r.reason, r.message);
            await sdk.waitForCondition((s) => s.player?.combat?.inCombat === true, 4000).catch(() => {});
            await sdk.waitForCondition((s) => s.player?.combat?.inCombat === false, 35000).catch(() => {});
            kills++;
            console.log('fight done, hp', sdk.getState()?.player.hp, 'attacks', attacks);
        } catch (e) {
            console.log('loop err', String(e));
        }
    }
    console.log('END attacks', attacks, 'hp', sdk.getState()?.player?.hp);
}, { timeout: 300_000 });

